import glob,json,os
for f in glob.glob('factors/*.json'):
 if f.endswith('factor_ensemble.json'): continue
 try:
  d=json.load(open(f)); status=d.get('status','')
  if status:
   m=d.get('validation_metrics',d.get('metrics',{}))
   print(os.path.basename(f),status, 'IC',m.get('ic',m.get('daily_ic')), 'ICIR',m.get('icir',m.get('daily_icir')), 'turn',m.get('rank_turnover',m.get('turnover')))
 except Exception as e: print('ERR',f,e)
PY

