arguments.command:
python - <<'PY'
import glob,json,os
for f in glob.glob('factors/*.json'):
 if f.endswith('.bak') or f.endswith('factor_ensemble.json'): continue
 try:
  d=json.load(open(f)); print(os.path.basename(f), d.get('ic'), d.get('icir'), d.get('daily_icir'), d.get('turnover'), d.get('category'))
 except Exception as e: print('ERR',f,e)
PY

