python - <<'PY'
import glob,csv,os,datetime,numpy as np
from math import sqrt
D={}
for p in glob.glob('../persistent/stock_data/*.csv'):
 s=os.path.basename(p)[:-4]; rows=[]
 with open(p) as f:
  for r in csv.reader(f):
   if r and r[0]<='2031-05-31':
    try: rows.append((r[0],float(r[2])))
    except: pass
 D[s]=dict(rows)
dates=sorted(set.intersection(*[set(x) for x in D.values()]))
for n in [5,20,60]:
 ds=dates[-n-1:]; vals=[]
 for s in D:
  if ds[0] in D[s] and ds[-1] in D[s]: vals.append((s,D[s][ds[-1]]/D[s][ds[0]]-1))
 print(n, 'mean',np.mean([x[1] for x in vals]),'positive',sum(x[1]>0 for x in vals),'range',min(vals,key=lambda x:x[1]),max(vals,key=lambda x:x[1]))
rets=[]
for s in D:
 v=np.array([D[s][d] for d in dates[-21:]])
 rets.append(np.diff(v)/v[:-1])
print('ann vol mean20',np.mean(np.std(rets,axis=1)*sqrt(252)), 'corr',np.mean(np.corrcoef(rets)))
# macro vix
p='../persistent/index_data/VIX.csv'; rows=[]
for r in csv.reader(open(p)):
 if r and r[0]<='2031-05-31':
  try: rows.append((r[0],float(r[2])))
  except: pass
print('vix',rows[-5:])
PY

